import { Circuit } from "@tscircuit/core"

// THS4541RGT EVM, SLOU392 Figure 1 (page 4), input termination extract.
// R26 has ground above its signal terminal; R25 has ground below.
// Both are populated 60.4-ohm resistors (Table 1, item 25, page 9).
// Net labels stand for the connections to the input network and U1
// outside this six-resistor extract; all labels are generated by traces.
export async function createTiThs4541InputTermination() {
  const circuit = new Circuit()
  circuit.pcbDisabled = true
  circuit.add(
    <board schLayout={{ layoutMode: "none" }} schMaxTraceDistance={4}>
      <net name="GND" isGroundNet />
      {/* Populated bypasses around the optional input transformer. */}
      <resistor
        symbolName="resistor"
        name="R3"
        resistance="0"
        schX={-2}
        schY={1}
      />
      <resistor
        symbolName="resistor"
        name="R4"
        resistance="0"
        schX={-2}
        schY={-1}
      />
      <trace from=".R3 > .pin1" to="net.J1_SIGNAL" />
      <trace from=".R4 > .pin1" to="net.J2_SIGNAL" />
      <trace from=".R3 > .pin2" to=".R26 > .pin1" />
      <trace from=".R4 > .pin2" to=".R25 > .pin1" />
      <resistor
        symbolName="resistor"
        name="R26"
        resistance="60.4"
        schX={0}
        schY={2.5}
        schRotation={90}
      />
      <resistor
        symbolName="resistor"
        name="R25"
        resistance="60.4"
        schX={0}
        schY={-2.5}
        schRotation={270}
      />
      <resistor
        symbolName="resistor"
        name="R7"
        resistance="191"
        schX={2}
        schY={1}
      />
      <resistor
        symbolName="resistor"
        name="R8"
        resistance="191"
        schX={2}
        schY={-1}
      />
      <trace from=".R26 > .pin2" to="net.GND" />
      <trace from=".R25 > .pin2" to="net.GND" />
      <trace from=".R26 > .pin1" to=".R7 > .pin1" />
      <trace from=".R25 > .pin1" to=".R8 > .pin1" />
      <trace from=".R26 > .pin1" to="net.INPUT_P" />
      <trace from=".R25 > .pin1" to="net.INPUT_N" />
      <trace from=".R7 > .pin2" to="net.U1_PIN_2" />
      <trace from=".R8 > .pin2" to="net.U1_PIN_3" />
    </board>,
  )
  await circuit.renderUntilSettled()
  return circuit.getCircuitJson()
}
